describe('Fallback provider model allowlist', () => {
  it('throws naming FALLBACK_MODEL_ID, gemini-2.5-flash and the allowed ids when FALLBACK_MODEL_ID gemini-2.5-flash is not in the table', () => {
    expect(() => getConfig({...requiredEnv, FALLBACK_MODEL_ID: 'gemini-2.5-flash'})).toThrow(
      /FALLBACK_MODEL_ID.*gemini-2.5-flash.*mock.*gemini-3.1-flash-lite/
    );
  });

  it('resolves a fallback whose table entry is pinned to europe-north1 against a fallback provider block whose residency field says us-east-1, and expects the same startup failure even though the id matches', () => {
    expect(() =>
      resolveModel(
        'europe-north1-test',
        {type: 'vertex', projectId: 'otto', location: 'us-east1', modelId: 'europe-north1-test'},
        [europeNorth1Entry]
      )
    ).toThrow(
      new Error(
        'Model "europe-north1-test" is pinned to region "europe-north1", but the provider block runs in "us-east1".'
      )
    );
  });

  it('resolves a fallback whose providerType is bedrock and asserts the model is read from modelId through the same switch 052 ships', () => {
    expect(
      resolveModel(
        'bedrock-fallback-test',
        {
          type: 'bedrock',
          modelId: 'bedrock-fallback-test',
          region: 'eu-central-1',
          maxTokens: 1024,
        },
        [bedrockFallbackEntry]
      )
    ).toEqual({providerType: 'bedrock', model: 'bedrock-fallback-test', region: 'eu-central-1'});
  });

  it('the resolver accepts every ProviderConfig in the assembled config', () => {
    const config = getConfig({...requiredEnv, FALLBACK_MODEL_ID: 'mock'});
    const resilience = config.resilience;
    expect(resilience?.fallback?.provider).toEqual({type: 'mock'});
  });

  it('asserts no fallback block is synthesised from the isDefault row when FALLBACK_MODEL_ID is unset', () => {
    const config = getConfig(requiredEnv);
    expect(config.resilience?.fallback).toBeUndefined();
  });

  it('refuses FALLBACK_MODEL_ID gemini-3.1-flash-lite before any config is built, naming its vertex row and KU-07', () => {
    expect(() => getConfig({...requiredEnv, FALLBACK_MODEL_ID: 'gemini-3.1-flash-lite'})).toThrow(
      new Error(
        'FALLBACK_MODEL_ID "gemini-3.1-flash-lite" names a vertex row, and only the mock row can be a fallback until a fallback vendor is chosen (KU-07).'
      )
    );
  });

  it('refuses the mock as the fallback of MODEL_ID gemini-3.1-flash-lite before any config is built, since it would echo each customer back', () => {
    const vertexPrimary = {
      ...requiredEnv,
      MODEL_ID: 'gemini-3.1-flash-lite',
      GCP_PROJECT_ID: 'otto-test',
      VERTEX_LOCATION: 'eu',
    };

    expect(() => getConfig({...vertexPrimary, FALLBACK_MODEL_ID: 'mock'})).toThrow(
      new Error(
        'FALLBACK_MODEL_ID "mock" would echo each customer\'s own message back as the answer whenever MODEL_ID "gemini-3.1-flash-lite" is unavailable. Unset FALLBACK_MODEL_ID.'
      )
    );
  });
});

